describe("Cart — async checkout()", () => {
  it("returns totals and lines without collaborators", async () => {
    const cart = new Cart();
    cart.add(product("a", 1000), 2);
    const result = await cart.checkout();
    expect(result.totals.subtotalCents).toBe(2000);
    expect(result.lines).toHaveLength(1);
  });

  it("refreshes prices via priceFetcher", async () => {
    const cart = new Cart();
    cart.add(product("a", 1000), 2);
    const priceFetcher: PriceFetcher = {
      fetchPriceCents: vi.fn().mockResolvedValue(1500),
    };
    const result = await cart.checkout({ priceFetcher });
    expect(result.totals.subtotalCents).toBe(3000); // 1500 * 2
    expect(result.lines[0]!.product.unitPriceCents).toBe(1500);
  });

  it("checks inventory and passes for available items", async () => {
    const cart = new Cart();
    cart.add(product("a", 1000), 2);
    const inventoryChecker: InventoryChecker = {
      check: vi.fn().mockResolvedValue({ available: true }),
    };
    const result = await cart.checkout({ inventoryChecker });
    expect(result.totals.subtotalCents).toBe(2000);
    expect(inventoryChecker.check).toHaveBeenCalledWith("a", 2);
  });

  it("throws InventoryError when item is unavailable", async () => {
    const cart = new Cart();
    cart.add(product("a", 1000), 5);
    const inventoryChecker: InventoryChecker = {
      check: vi.fn().mockResolvedValue({
        available: false,
        reason: "sold out",
      }),
    };
    try {
      await cart.checkout({ inventoryChecker });
      expect.fail("should have thrown");
    } catch (err) {
      expect(err).toBeInstanceOf(InventoryError);
      const invErr = err as InventoryError;
      expect(invErr.productId).toBe("a");
      expect(invErr.requested).toBe(5);
      expect(invErr.message).toBe("sold out");
    }
  });

  it("throws InventoryError for partial-stock denial", async () => {
    const cart = new Cart();
    cart.add(product("a", 1000), 10);
    const inventoryChecker: InventoryChecker = {
      check: vi.fn().mockResolvedValue({
        available: true,
        availableQuantity: 3,
      }),
    };
    try {
      await cart.checkout({ inventoryChecker });
      expect.fail("should have thrown");
    } catch (err) {
      expect(err).toBeInstanceOf(InventoryError);
      const invErr = err as InventoryError;
      expect(invErr.productId).toBe("a");
      expect(invErr.requested).toBe(10);
      expect(invErr.available).toBe(3);
    }
  });

  it("uses asyncTaxProvider when supplied", async () => {
    const tax: TaxCalculator = {
      computeTaxCents: vi.fn().mockReturnValue(0),
    };
    const cart = new Cart({ taxCalculator: tax });
    cart.add(product("a", 1000), 1);

    const asyncTaxProvider: AsyncTaxRateProvider = {
      getRate: vi.fn().mockResolvedValue(0.1),
    };
    const result = await cart.checkout({ asyncTaxProvider });
    // Async tax: 10% of 1000 = 100
    expect(result.totals.taxCents).toBe(100);
    // The sync tax calculator should NOT be used for the tax computation
    // (asyncTaxProvider replaces it)
  });

  it("combines priceFetcher + discount + asyncTax + shipping", async () => {
    const discount: DiscountPolicy = {
      computeDiscountCents: vi.fn().mockReturnValue(500),
    };
    const shipping: ShippingCalculator = {
      computeShippingCents: vi.fn().mockReturnValue(300),
    };
    const cart = new Cart({ discountPolicy: discount, shippingCalculator: shipping });
    cart.add(product("a", 2000), 1);

    const priceFetcher: PriceFetcher = {
      fetchPriceCents: vi.fn().mockResolvedValue(3000),
    };
    const asyncTaxProvider: AsyncTaxRateProvider = {
      getRate: vi.fn().mockResolvedValue(0.08),
    };
    const result = await cart.checkout({ priceFetcher, asyncTaxProvider });
    // Updated price: 3000, discount: 500, discounted: 2500
    // Tax: 8% of 2500 = 200, shipping: 300
    expect(result.totals.subtotalCents).toBe(3000);
    expect(result.totals.discountCents).toBe(500);
    expect(result.totals.taxCents).toBe(200);
    expect(result.totals.shippingCents).toBe(300);
    expect(result.totals.totalCents).toBe(2500 + 200 + 300);
  });

  it("propagates asyncTaxProvider rejection", async () => {
    const cart = new Cart();
    cart.add(product("a", 1000), 1);
    const asyncTaxProvider: AsyncTaxRateProvider = {
      getRate: vi.fn().mockRejectedValue(new Error("tax service down")),
    };
    await expect(cart.checkout({ asyncTaxProvider })).rejects.toThrow(
      "tax service down",
    );
  });

  it("propagates priceFetcher rejection", async () => {
    const cart = new Cart();
    cart.add(product("a", 1000), 1);
    const priceFetcher: PriceFetcher = {
      fetchPriceCents: vi.fn().mockRejectedValue(new Error("price API down")),
    };
    await expect(cart.checkout({ priceFetcher })).rejects.toThrow(
      "price API down",
    );
  });

  it("checks inventory for each line — first denial wins", async () => {
    const cart = new Cart();
    cart.add(product("a", 1000), 1);
    cart.add(product("b", 2000), 1);
    const inventoryChecker: InventoryChecker = {
      check: vi
        .fn()
        .mockResolvedValueOnce({ available: true })
        .mockResolvedValueOnce({
          available: false,
          reason: "b is out of stock",
        }),
    };
    try {
      await cart.checkout({ inventoryChecker });
      expect.fail("should have thrown");
    } catch (err) {
      expect(err).toBeInstanceOf(InventoryError);
      expect((err as InventoryError).productId).toBe("b");
    }
  });

  it("checkout on empty cart returns zero totals", async () => {
    const cart = new Cart();
    const result = await cart.checkout();
    expect(result.totals.totalCents).toBe(0);
    expect(result.lines).toEqual([]);
  });
});

import { describe, it, expect } from "vitest";
import {
  NoDiscountPolicy,
  PercentageDiscountPolicy,
  FixedAmountDiscountPolicy,
  CompositeDiscountPolicy,
} from "../src/pricing.ts";

describe("NoDiscountPolicy", () => {
  const policy = new NoDiscountPolicy();

  it.each([0, 100, 99999])("returns 0 for subtotal %i", (subtotal) => {
    expect(policy.computeDiscountCents(subtotal)).toBe(0);
  });

  it("returns 0 for negative subtotal", () => {
    expect(policy.computeDiscountCents(-500)).toBe(0);
  });
});

describe("PercentageDiscountPolicy", () => {
  describe("constructor validation", () => {
    it.each([-1, 101, NaN, Infinity, -Infinity])(
      "rejects out-of-range percent %s",
      (percent) => {
        expect(() => new PercentageDiscountPolicy(percent)).toThrow(RangeError);
      },
    );

    it.each([0, 50, 100])("accepts valid percent %i", (percent) => {
      expect(() => new PercentageDiscountPolicy(percent)).not.toThrow();
    });
  });

  it("computes 10% of 1000 = 100", () => {
    const policy = new PercentageDiscountPolicy(10);
    expect(policy.computeDiscountCents(1000)).toBe(100);
  });

  it("rounds down to nearest cent", () => {
    // 33% of 100 = 33.0 exactly, but 33% of 101 = 33.33 → 33
    const policy = new PercentageDiscountPolicy(33);
    expect(policy.computeDiscountCents(101)).toBe(33);
  });

  it("returns 0 for zero subtotal", () => {
    const policy = new PercentageDiscountPolicy(50);
    expect(policy.computeDiscountCents(0)).toBe(0);
  });

  it("returns 0 for negative subtotal", () => {
    const policy = new PercentageDiscountPolicy(25);
    expect(policy.computeDiscountCents(-100)).toBe(0);
  });

  it("100% discount equals full subtotal", () => {
    const policy = new PercentageDiscountPolicy(100);
    expect(policy.computeDiscountCents(5000)).toBe(5000);
  });

  it("0% discount returns 0", () => {
    const policy = new PercentageDiscountPolicy(0);
    expect(policy.computeDiscountCents(5000)).toBe(0);
  });

  it("handles very large subtotal", () => {
    const policy = new PercentageDiscountPolicy(15);
    expect(policy.computeDiscountCents(1_000_000_00)).toBe(15_000_000);
  });
});

describe("FixedAmountDiscountPolicy", () => {
  describe("constructor validation", () => {
    it("rejects negative amount", () => {
      expect(() => new FixedAmountDiscountPolicy(-1)).toThrow(RangeError);
    });

    it("rejects non-integer amount", () => {
      expect(() => new FixedAmountDiscountPolicy(10.5)).toThrow(RangeError);
    });

    it("accepts zero", () => {
      expect(() => new FixedAmountDiscountPolicy(0)).not.toThrow();
    });
  });

  it("returns fixed amount when subtotal exceeds it", () => {
    const policy = new FixedAmountDiscountPolicy(500);
    expect(policy.computeDiscountCents(1000)).toBe(500);
  });

  it("caps discount at subtotal when subtotal is smaller", () => {
    const policy = new FixedAmountDiscountPolicy(500);
    expect(policy.computeDiscountCents(300)).toBe(300);
  });

  it("returns 0 for zero subtotal", () => {
    const policy = new FixedAmountDiscountPolicy(500);
    expect(policy.computeDiscountCents(0)).toBe(0);
  });

  it("returns 0 for negative subtotal", () => {
    const policy = new FixedAmountDiscountPolicy(500);
    expect(policy.computeDiscountCents(-100)).toBe(0);
  });

  it("returns exact subtotal when amount equals subtotal", () => {
    const policy = new FixedAmountDiscountPolicy(1000);
    expect(policy.computeDiscountCents(1000)).toBe(1000);
  });
});

describe("CompositeDiscountPolicy", () => {
  it("rejects empty policies array", () => {
    expect(() => new CompositeDiscountPolicy([])).toThrow(
      "CompositeDiscountPolicy requires at least one policy",
    );
  });

  describe("sum mode", () => {
    it("sums discounts from multiple policies", () => {
      const composite = new CompositeDiscountPolicy(
        [new PercentageDiscountPolicy(10), new FixedAmountDiscountPolicy(200)],
        "sum",
      );
      // 10% of 1000 = 100, fixed 200 → 300
      expect(composite.computeDiscountCents(1000)).toBe(300);
    });

    it("each policy receives the original subtotal", () => {
      const composite = new CompositeDiscountPolicy(
        [new PercentageDiscountPolicy(50), new PercentageDiscountPolicy(50)],
        "sum",
      );
      // Both see 1000 → 500 + 500 = 1000
      expect(composite.computeDiscountCents(1000)).toBe(1000);
    });

    it("returns 0 for zero subtotal", () => {
      const composite = new CompositeDiscountPolicy(
        [new PercentageDiscountPolicy(10), new FixedAmountDiscountPolicy(500)],
        "sum",
      );
      expect(composite.computeDiscountCents(0)).toBe(0);
    });

    it("returns 0 for negative subtotal", () => {
      const composite = new CompositeDiscountPolicy(
        [new FixedAmountDiscountPolicy(100)],
        "sum",
      );
      expect(composite.computeDiscountCents(-50)).toBe(0);
    });

    it("clamps negative child-policy results to 0", () => {
      // A custom policy returning negative — sum mode should Math.max(0, ...)
      const negativePolicy = {
        computeDiscountCents: () => -100,
      };
      const composite = new CompositeDiscountPolicy(
        [negativePolicy, new FixedAmountDiscountPolicy(200)],
        "sum",
      );
      expect(composite.computeDiscountCents(1000)).toBe(200);
    });
  });

  describe("chain mode", () => {
    it("applies discounts sequentially on remaining subtotal", () => {
      // 50% of 1000 = 500 (remaining 500), then 50% of 500 = 250
      const composite = new CompositeDiscountPolicy(
        [new PercentageDiscountPolicy(50), new PercentageDiscountPolicy(50)],
        "chain",
      );
      expect(composite.computeDiscountCents(1000)).toBe(750);
    });

    it("order matters in chain mode", () => {
      // Fixed 300 first (remaining 700), then 10% of 700 = 70 → total 370
      const composite1 = new CompositeDiscountPolicy(
        [new FixedAmountDiscountPolicy(300), new PercentageDiscountPolicy(10)],
        "chain",
      );
      // 10% of 1000 = 100 first (remaining 900), then fixed 300 → total 400
      const composite2 = new CompositeDiscountPolicy(
        [new PercentageDiscountPolicy(10), new FixedAmountDiscountPolicy(300)],
        "chain",
      );
      expect(composite1.computeDiscountCents(1000)).toBe(370);
      expect(composite2.computeDiscountCents(1000)).toBe(400);
    });

    it("caps each step at remaining subtotal", () => {
      // Fixed 800 (remaining 200), then Fixed 500 (capped at 200)
      const composite = new CompositeDiscountPolicy(
        [new FixedAmountDiscountPolicy(800), new FixedAmountDiscountPolicy(500)],
        "chain",
      );
      expect(composite.computeDiscountCents(1000)).toBe(1000);
    });

    it("returns 0 for zero subtotal", () => {
      const composite = new CompositeDiscountPolicy(
        [new PercentageDiscountPolicy(10)],
        "chain",
      );
      expect(composite.computeDiscountCents(0)).toBe(0);
    });

    it("clamps negative child-policy results to 0 before applying", () => {
      const negativePolicy = { computeDiscountCents: () => -50 };
      const composite = new CompositeDiscountPolicy(
        [negativePolicy, new FixedAmountDiscountPolicy(100)],
        "chain",
      );
      // negative → 0, so remaining stays 1000, then fixed 100
      expect(composite.computeDiscountCents(1000)).toBe(100);
    });
  });

  it("defaults to sum mode when mode is omitted", () => {
    const composite = new CompositeDiscountPolicy([
      new PercentageDiscountPolicy(10),
      new FixedAmountDiscountPolicy(200),
    ]);
    // sum: 10% of 1000 = 100 + 200 = 300
    expect(composite.computeDiscountCents(1000)).toBe(300);
  });
});

