  });
});

describe("WeightBasedShippingCalculator", () => {
  const brackets = [
    { upToGrams: 500, costCents: 300 },
    { upToGrams: 2000, costCents: 700 },
    { upToGrams: 5000, costCents: 1200 },
  ];

  describe("constructor validation", () => {
    it("rejects empty brackets", () => {
      expect(() => new WeightBasedShippingCalculator([])).toThrow(
        "at least one weight bracket is required",
      );
    });

    it("rejects bracket with non-positive upToGrams", () => {
      expect(
        () => new WeightBasedShippingCalculator([{ upToGrams: 0, costCents: 100 }]),
      ).toThrow(RangeError);
    });

    it("rejects bracket with negative costCents", () => {
      expect(
        () => new WeightBasedShippingCalculator([{ upToGrams: 500, costCents: -1 }]),
      ).toThrow(RangeError);
    });

    it("rejects non-integer upToGrams", () => {
      expect(
        () => new WeightBasedShippingCalculator([{ upToGrams: 1.5, costCents: 100 }]),
      ).toThrow(RangeError);
    });

    it("rejects non-integer costCents", () => {
      expect(
        () => new WeightBasedShippingCalculator([{ upToGrams: 500, costCents: 1.5 }]),
      ).toThrow(RangeError);
    });

    it("rejects negative overflowCostCents", () => {
      expect(
        () => new WeightBasedShippingCalculator(
          [{ upToGrams: 500, costCents: 100 }],
          -1,
        ),
      ).toThrow(RangeError);
    });

    it("rejects non-integer overflowCostCents", () => {
      expect(
        () => new WeightBasedShippingCalculator(
          [{ upToGrams: 500, costCents: 100 }],
          5.5,
        ),
      ).toThrow(RangeError);
    });
  });

  it("returns 0 for empty cart", () => {
    const calc = new WeightBasedShippingCalculator(brackets);
    expect(calc.computeShippingCents([], 1000)).toBe(0);
  });

  it("returns 0 when total weight is 0 (products without weight)", () => {
    const calc = new WeightBasedShippingCalculator(brackets);
    expect(calc.computeShippingCents([line("a", 100, 2)], 200)).toBe(0);
  });

  it("selects first bracket when weight is within it", () => {
    const calc = new WeightBasedShippingCalculator(brackets);
    expect(calc.computeShippingCents([line("a", 100, 1, 400)], 100)).toBe(300);
  });

  it("selects bracket at boundary (weight equals upToGrams)", () => {
    const calc = new WeightBasedShippingCalculator(brackets);
    expect(calc.computeShippingCents([line("a", 100, 1, 500)], 100)).toBe(300);
  });

  it("selects next bracket when weight exceeds boundary", () => {
    const calc = new WeightBasedShippingCalculator(brackets);
    expect(calc.computeShippingCents([line("a", 100, 1, 501)], 100)).toBe(700);
  });

  it("selects highest bracket at its boundary", () => {
    const calc = new WeightBasedShippingCalculator(brackets);
    expect(calc.computeShippingCents([line("a", 100, 1, 5000)], 100)).toBe(1200);
  });

  it("uses overflow cost when weight exceeds all brackets", () => {
    const calc = new WeightBasedShippingCalculator(brackets, 2000);
    expect(calc.computeShippingCents([line("a", 100, 1, 6000)], 100)).toBe(2000);
  });

  it("falls back to heaviest bracket cost when no overflow is set", () => {
    const calc = new WeightBasedShippingCalculator(brackets);
    expect(calc.computeShippingCents([line("a", 100, 1, 6000)], 100)).toBe(1200);
  });

  it("sorts brackets internally regardless of input order", () => {
    const unordered = [
      { upToGrams: 5000, costCents: 1200 },
      { upToGrams: 500, costCents: 300 },
      { upToGrams: 2000, costCents: 700 },
    ];
    const calc = new WeightBasedShippingCalculator(unordered);
    expect(calc.computeShippingCents([line("a", 100, 1, 400)], 100)).toBe(300);
    expect(calc.computeShippingCents([line("a", 100, 1, 1500)], 100)).toBe(700);
  });

  it("accumulates weight across multiple lines", () => {
    const calc = new WeightBasedShippingCalculator(brackets);
    const lines = [
      line("a", 100, 2, 300), // 600g
      line("b", 200, 1, 500), // 500g → total 1100g → bracket 2000
    ];
    expect(calc.computeShippingCents(lines, 400)).toBe(700);
  });
});

import { describe, it, expect, vi } from "vitest";
import {
  InventoryError,
  refreshPrices,
  type PriceFetcher,
} from "../src/inventory.ts";
import type { CartLine } from "../src/product.ts";

const mkLine = (id: string, price: number, qty: number): CartLine => ({
  product: { id, name: id, unitPriceCents: price },
  quantity: qty,
});

describe("InventoryError", () => {
  it("has correct name and properties", () => {
    const err = new InventoryError("out of stock", "prod-1", 5, 2);
    expect(err).toBeInstanceOf(Error);
    expect(err.name).toBe("InventoryError");
    expect(err.message).toBe("out of stock");
    expect(err.productId).toBe("prod-1");
    expect(err.requested).toBe(5);
    expect(err.available).toBe(2);
  });

  it("allows undefined available", () => {
    const err = new InventoryError("gone", "prod-2", 3, undefined);
    expect(err.available).toBeUndefined();
  });
});

describe("refreshPrices", () => {
  it("updates prices from fetcher", async () => {
    const fetcher: PriceFetcher = {
      fetchPriceCents: vi.fn()
        .mockResolvedValueOnce(1500)
        .mockResolvedValueOnce(2500),
    };
    const lines = [mkLine("a", 100, 2), mkLine("b", 200, 1)];
    const result = await refreshPrices(lines, fetcher);

    expect(result).toHaveLength(2);
    expect(result[0]!.product.unitPriceCents).toBe(1500);
    expect(result[0]!.quantity).toBe(2);
    expect(result[1]!.product.unitPriceCents).toBe(2500);
    expect(result[1]!.quantity).toBe(1);
  });

  it("preserves other product fields", async () => {
    const fetcher: PriceFetcher = {
      fetchPriceCents: vi.fn().mockResolvedValue(999),
    };
    const lines: CartLine[] = [
      {
        product: { id: "x", name: "Widget", unitPriceCents: 100, weightGrams: 500, currency: "EUR" },
        quantity: 1,
      },
    ];
    const result = await refreshPrices(lines, fetcher);
    expect(result[0]!.product.name).toBe("Widget");
    expect(result[0]!.product.weightGrams).toBe(500);
    expect(result[0]!.product.currency).toBe("EUR");
  });

  it("throws RangeError for negative price", async () => {
    const fetcher: PriceFetcher = {
      fetchPriceCents: vi.fn().mockResolvedValue(-1),
    };
    await expect(refreshPrices([mkLine("a", 100, 1)], fetcher)).rejects.toThrow(
      RangeError,
    );
  });

  it("throws RangeError for non-integer price", async () => {
    const fetcher: PriceFetcher = {
      fetchPriceCents: vi.fn().mockResolvedValue(10.5),
    };
    await expect(refreshPrices([mkLine("a", 100, 1)], fetcher)).rejects.toThrow(
      RangeError,
    );
  });

  it("propagates fetcher rejection", async () => {
    const fetcher: PriceFetcher = {
      fetchPriceCents: vi.fn().mockRejectedValue(new Error("fetch failed")),
    };
    await expect(refreshPrices([mkLine("a", 100, 1)], fetcher)).rejects.toThrow(
      "fetch failed",
    );
  });

  it("returns empty array for empty lines", async () => {
    const fetcher: PriceFetcher = {
      fetchPriceCents: vi.fn(),
    };
    const result = await refreshPrices([], fetcher);
    expect(result).toEqual([]);
    expect(fetcher.fetchPriceCents).not.toHaveBeenCalled();
  });
});

import { describe, it, expect, vi, beforeEach } from "vitest";
import { Cart } from "../src/cart.ts";
import { InventoryError } from "../src/inventory.ts";
import type { Product } from "../src/product.ts";
import type { DiscountPolicy } from "../src/pricing.ts";
import type { TaxCalculator } from "../src/tax.ts";
import type { ShippingCalculator } from "../src/shipping.ts";
import type { PriceFetcher, InventoryChecker } from "../src/inventory.ts";
import type { AsyncTaxRateProvider } from "../src/tax.ts";

const product = (id: string, price: number, weight?: number): Product => ({
  id,
  name: `Product ${id}`,
  unitPriceCents: price,
  weightGrams: weight,
});

describe("Cart — line management", () => {
  let cart: Cart;

  beforeEach(() => {
    cart = new Cart();
  });

  it("starts empty with itemCount 0", () => {
    expect(cart.itemCount).toBe(0);
    expect(cart.snapshot()).toEqual([]);
  });

  it("adds a product", () => {
    cart.add(product("a", 500), 2);
    expect(cart.itemCount).toBe(2);
    const snap = cart.snapshot();
    expect(snap).toHaveLength(1);
    expect(snap[0]!.product.id).toBe("a");
    expect(snap[0]!.quantity).toBe(2);
  });

  it("merges quantity when adding the same product twice", () => {
    cart.add(product("a", 500), 2);
    cart.add(product("a", 500), 3);
    expect(cart.itemCount).toBe(5);
    expect(cart.snapshot()).toHaveLength(1);
    expect(cart.snapshot()[0]!.quantity).toBe(5);
  });

  it("rejects non-positive quantity on add", () => {
    expect(() => cart.add(product("a", 500), 0)).toThrow(RangeError);
    expect(() => cart.add(product("a", 500), -1)).toThrow(RangeError);
  });

  it("rejects non-integer quantity on add", () => {
    expect(() => cart.add(product("a", 500), 1.5)).toThrow(RangeError);
  });

  it("rejects negative unitPriceCents on add", () => {
    expect(() => cart.add(product("a", -1), 1)).toThrow(RangeError);
  });

  it("removes a product and returns true", () => {
    cart.add(product("a", 500), 1);
    expect(cart.remove("a")).toBe(true);
    expect(cart.itemCount).toBe(0);
  });

  it("returns false when removing an unknown product", () => {
    expect(cart.remove("unknown")).toBe(false);
  });

  it("updates quantity for an existing product", () => {
    cart.add(product("a", 500), 2);
    cart.updateQuantity("a", 5);
    expect(cart.itemCount).toBe(5);
  });

  it("removes product when updating quantity to 0", () => {
    cart.add(product("a", 500), 2);
    cart.updateQuantity("a", 0);
    expect(cart.itemCount).toBe(0);
    expect(cart.snapshot()).toEqual([]);
  });

  it("throws on updateQuantity for unknown product", () => {
    expect(() => cart.updateQuantity("unknown", 5)).toThrow(
      "Product unknown is not in the cart",
    );
  });

  it("throws on updateQuantity with negative quantity", () => {
    cart.add(product("a", 500), 1);
    expect(() => cart.updateQuantity("a", -1)).toThrow(RangeError);
  });

  it("throws on updateQuantity with non-integer quantity", () => {
    cart.add(product("a", 500), 1);
    expect(() => cart.updateQuantity("a", 1.5)).toThrow(RangeError);
  });

  it("clears all lines", () => {
    cart.add(product("a", 500), 1);
    cart.add(product("b", 300), 2);
    cart.clear();
    expect(cart.itemCount).toBe(0);
    expect(cart.snapshot()).toEqual([]);
  });

  it("snapshot is a deep copy — mutation does not affect cart", () => {
    cart.add(product("a", 500), 1);
    const snap = cart.snapshot();
    snap[0]!.quantity = 999;
    snap[0]!.product.unitPriceCents = 0;
    expect(cart.snapshot()[0]!.quantity).toBe(1);
    expect(cart.snapshot()[0]!.product.unitPriceCents).toBe(500);
  });
});

describe("Cart — totals with mocked seams", () => {
  it("computes subtotal as sum of price * quantity", () => {
    const cart = new Cart();
    cart.add(product("a", 1000), 2);
    cart.add(product("b", 500), 3);
    const totals = cart.totals();
    expect(totals.subtotalCents).toBe(3500); // 2000 + 1500
  });

  it("returns all-zero totals for empty cart", () => {
    const cart = new Cart();
    const totals = cart.totals();
    expect(totals).toEqual({
      subtotalCents: 0,
      discountCents: 0,
      taxCents: 0,
      shippingCents: 0,
      totalCents: 0,
    });
  });

  it("applies discount policy and clamps to [0, subtotal]", () => {
    const discount: DiscountPolicy = {
      computeDiscountCents: vi.fn().mockReturnValue(300),
    };
    const cart = new Cart({ discountPolicy: discount });
    cart.add(product("a", 1000), 1);
    const totals = cart.totals();
    expect(totals.discountCents).toBe(300);
    expect(totals.totalCents).toBe(700); // 1000 - 300
  });

  it("clamps negative discount to 0", () => {
    const discount: DiscountPolicy = {
      computeDiscountCents: vi.fn().mockReturnValue(-500),
    };
    const cart = new Cart({ discountPolicy: discount });
    cart.add(product("a", 1000), 1);
    expect(cart.totals().discountCents).toBe(0);
    expect(cart.totals().totalCents).toBe(1000);
  });

  it("clamps discount exceeding subtotal to subtotal", () => {
    const discount: DiscountPolicy = {
      computeDiscountCents: vi.fn().mockReturnValue(9999),
    };
    const cart = new Cart({ discountPolicy: discount });
    cart.add(product("a", 1000), 1);
    expect(cart.totals().discountCents).toBe(1000);
    expect(cart.totals().totalCents).toBe(0);
  });

  it("computes tax on discounted subtotal", () => {
    const discount: DiscountPolicy = {
      computeDiscountCents: vi.fn().mockReturnValue(200),
    };
    const tax: TaxCalculator = {
      computeTaxCents: vi.fn().mockReturnValue(80),
    };
    const cart = new Cart({ discountPolicy: discount, taxCalculator: tax });
    cart.add(product("a", 1000), 1);
    const totals = cart.totals();
    // Tax called with discounted subtotal (1000 - 200 = 800)
    expect(tax.computeTaxCents).toHaveBeenCalledWith(800, "US");
    expect(totals.taxCents).toBe(80);
  });

  it("passes region to tax calculator", () => {
    const tax: TaxCalculator = {
      computeTaxCents: vi.fn().mockReturnValue(0),
    };
    const cart = new Cart({ taxCalculator: tax, region: "FR" });
    cart.add(product("a", 100), 1);
    cart.totals();
    expect(tax.computeTaxCents).toHaveBeenCalledWith(100, "FR");
  });

  it("clamps negative tax to 0", () => {
    const tax: TaxCalculator = {
      computeTaxCents: vi.fn().mockReturnValue(-50),
    };
    const cart = new Cart({ taxCalculator: tax });
    cart.add(product("a", 1000), 1);
    expect(cart.totals().taxCents).toBe(0);
  });

  it("passes lines and discounted subtotal to shipping calculator", () => {
    const discount: DiscountPolicy = {
      computeDiscountCents: vi.fn().mockReturnValue(100),
    };
    const shipping: ShippingCalculator = {
      computeShippingCents: vi.fn().mockReturnValue(500),
    };
    const cart = new Cart({ discountPolicy: discount, shippingCalculator: shipping });
    cart.add(product("a", 1000), 1);
    const totals = cart.totals();
    expect(shipping.computeShippingCents).toHaveBeenCalledWith(
      expect.any(Array),
      900, // discounted subtotal
    );
    expect(totals.shippingCents).toBe(500);
  });

  it("clamps negative shipping to 0", () => {
    const shipping: ShippingCalculator = {
      computeShippingCents: vi.fn().mockReturnValue(-100),
    };
    const cart = new Cart({ shippingCalculator: shipping });
    cart.add(product("a", 1000), 1);
    expect(cart.totals().shippingCents).toBe(0);
  });

  it("totalCents = discountedSubtotal + tax + shipping", () => {
    const discount: DiscountPolicy = {
      computeDiscountCents: vi.fn().mockReturnValue(100),
    };
    const tax: TaxCalculator = {
      computeTaxCents: vi.fn().mockReturnValue(72),
    };
    const shipping: ShippingCalculator = {
      computeShippingCents: vi.fn().mockReturnValue(500),
    };
    const cart = new Cart({
      discountPolicy: discount,
      taxCalculator: tax,
      shippingCalculator: shipping,
    });
    cart.add(product("a", 1000), 1);
    const totals = cart.totals();
    // subtotal=1000, discount=100, discounted=900, tax=72, shipping=500
    expect(totals.totalCents).toBe(900 + 72 + 500);
  });

  it("uses defaults when no config provided", () => {
    const cart = new Cart();
    cart.add(product("a", 1000), 1);
    const totals = cart.totals();
    expect(totals.discountCents).toBe(0);
    expect(totals.taxCents).toBe(0);
    expect(totals.shippingCents).toBe(0);
    expect(totals.totalCents).toBe(1000);
  });
});

describe("Cart — async checkout()", () => {
  it("returns totals and lines without collaborators", async () => {
    const cart = new Cart();
    cart.add(product("a", 1000), 2);
    const result = await cart.checkout();
    expect(result.totals.subtotalCents).toBe(2000);
    expect(result.lines).toHaveLength(1);
  });

  it("refreshes prices via priceFetcher", async () => {
    const cart = new Cart();
    cart.add(product("a", 1000), 2);
    const priceFetcher: PriceFetcher = {
      fetchPriceCents: vi.fn().mockResolvedValue(1500),
    };
    const result = await cart.checkout({ priceFetcher });
    expect(result.totals.subtotalCents).toBe(3000); // 1500 * 2
    expect(result.lines[0]!.product.unitPriceCents).toBe(1500);
  });

  it("checks inventory and passes for available items", async () => {
    const cart = new Cart();
    cart.add(product("a", 1000), 2);
    const inventoryChecker: InventoryChecker = {
      check: vi.fn().mockResolvedValue({ available: true }),
    };
    const result = await cart.checkout({ inventoryChecker });
    expect(result.totals.subtotalCents).toBe(2000);
    expect(inventoryChecker.check).toHaveBeenCalledWith("a", 2);
  });

  it("throws InventoryError when item is unavailable", async () => {
    const cart = new Cart();
    cart.add(product("a", 1000), 5);
    const inventoryChecker: InventoryChecker = {
      check: vi.fn().mockResolvedValue({
        available: false,
        reason: "sold out",
      }),
    };
    try {
      await cart.checkout({ inventoryChecker });
      expect.fail("should have thrown");
    } catch (err) {
      expect(err).toBeInstanceOf(InventoryError);
      const invErr = err as InventoryError;
      expect(invErr.productId).toBe("a");
      expect(invErr.requested).toBe(5);
      expect(invErr.message).toBe("sold out");
    }
  });

  it("throws InventoryError for partial-stock denial", async () => {
    const cart = new Cart();
    cart.add(product("a", 1000), 10);
    const inventoryChecker: InventoryChecker = {
      check: vi.fn().mockResolvedValue({
        available: true,
        availableQuantity: 3,
      }),
    };
    try {
      await cart.checkout({ inventoryChecker });
      expect.fail("should have thrown");
    } catch (err) {
      expect(err).toBeInstanceOf(InventoryError);
      const invErr = err as InventoryError;
      expect(invErr.productId).toBe("a");
      expect(invErr.requested).toBe(10);
      expect(invErr.available).toBe(3);
    }
  });

  it("uses asyncTaxProvider when supplied", async () => {
    const tax: TaxCalculator = {
      computeTaxCents: vi.fn().mockReturnValue(0),
    };
    const cart = new Cart({ taxCalculator: tax });
    cart.add(product("a", 1000), 1);

    const asyncTaxProvider: AsyncTaxRateProvider = {
      getRate: vi.fn().mockResolvedValue(0.1),
    };
    const result = await cart.checkout({ asyncTaxProvider });
    // Async tax: 10% of 1000 = 100
    expect(result.totals.taxCents).toBe(100);
    // The sync tax calculator should NOT be used for the tax computation
    // (asyncTaxProvider replaces it)
  });

  it("combines priceFetcher + discount + asyncTax + shipping", async () => {
    const discount: DiscountPolicy = {
      computeDiscountCents: vi.fn().mockReturnValue(500),
    };
    const shipping: ShippingCalculator = {
      computeShippingCents: vi.fn().mockReturnValue(300),
    };
    const cart = new Cart({ discountPolicy: discount, shippingCalculator: shipping });
    cart.add(product("a", 2000), 1);

    const priceFetcher: PriceFetcher = {
      fetchPriceCents: vi.fn().mockResolvedValue(3000),
    };
    const asyncTaxProvider: AsyncTaxRateProvider = {
      getRate: vi.fn().mockResolvedValue(0.08),
    };
    const result = await cart.checkout({ priceFetcher, asyncTaxProvider });
    // Updated price: 3000, discount: 500, discounted: 2500
    // Tax: 8% of 2500 = 200, shipping: 300
    expect(result.totals.subtotalCents).toBe(3000);
    expect(result.totals.discountCents).toBe(500);
    expect(result.totals.taxCents).toBe(200);
    expect(result.totals.shippingCents).toBe(300);
    expect(result.totals.totalCents).toBe(2500 + 200 + 300);
  });

  it("propagates asyncTaxProvider rejection", async () => {
    const cart = new Cart();
    cart.add(product("a", 1000), 1);
    const asyncTaxProvider: AsyncTaxRateProvider = {
      getRate: vi.fn().mockRejectedValue(new Error("tax service down")),
    };
    await expect(cart.checkout({ asyncTaxProvider })).rejects.toThrow(
      "tax service down",
    );
  });

  it("propagates priceFetcher rejection", async () => {
    const cart = new Cart();
    cart.add(product("a", 1000), 1);
    const priceFetcher: PriceFetcher = {
      fetchPriceCents: vi.fn().mockRejectedValue(new Error("price API down")),
    };
    await expect(cart.checkout({ priceFetcher })).rejects.toThrow(
      "price API down",
    );
  });

  it("checks inventory for each line — first denial wins", async () => {
    const cart = new Cart();
    cart.add(product("a", 1000), 1);
    cart.add(product("b", 2000), 1);
    const inventoryChecker: InventoryChecker = {
      check: vi
        .fn()
        .mockResolvedValueOnce({ available: true })
        .mockResolvedValueOnce({
          available: false,
          reason: "b is out of stock",
        }),
    };
