toolArgs.file_text:
import { describe, it, expect, vi } from "vitest";
import {
  NoTaxCalculator,
  RegionalTaxCalculator,
  AsyncTaxCalculator,
  totalLineWeightGrams,
  type AsyncTaxRateProvider,
} from "../src/tax.ts";
import type { CartLine } from "../src/product.ts";

describe("NoTaxCalculator", () => {
  const calc = new NoTaxCalculator();

  it("returns 0 regardless of inputs", () => {
    expect(calc.computeTaxCents(5000, "US")).toBe(0);
    expect(calc.computeTaxCents(0, "FR")).toBe(0);
  });
});

describe("RegionalTaxCalculator", () => {
  describe("constructor validation", () => {
    it.each([-0.01, 1.01, NaN, Infinity])(
      "rejects defaultRate %s",
      (rate) => {
        expect(() => new RegionalTaxCalculator({}, rate)).toThrow(RangeError);
      },
    );

    it("rejects invalid rate in rates map", () => {
      expect(
        () => new RegionalTaxCalculator({ "US": -0.1 }),
      ).toThrow(RangeError);
    });

    it("rejects rate > 1 in rates map", () => {
      expect(
        () => new RegionalTaxCalculator({ "US": 1.5 }),
      ).toThrow(RangeError);
    });

    it("accepts valid rates", () => {
      expect(
        () => new RegionalTaxCalculator({ "US": 0.08, "FR": 0.2 }, 0.1),
      ).not.toThrow();
    });
  });

  it("uses the region-specific rate", () => {
    const calc = new RegionalTaxCalculator({ "US-CA": 0.0875 });
    // 8.75% of 10000 = 875
    expect(calc.computeTaxCents(10000, "US-CA")).toBe(875);
  });

  it("falls back to defaultRate for unknown region", () => {
    const calc = new RegionalTaxCalculator({ "US": 0.08 }, 0.05);
    // 5% of 2000 = 100
    expect(calc.computeTaxCents(2000, "JP")).toBe(100);
  });

  it("uses 0 as defaultRate when not provided and region is unknown", () => {
    const calc = new RegionalTaxCalculator({ "US": 0.08 });
    expect(calc.computeTaxCents(2000, "JP")).toBe(0);
  });

  it("rounds down to nearest cent", () => {
    const calc = new RegionalTaxCalculator({ "US": 0.0875 });
    // 8.75% of 999 = 87.4125 → 87
    expect(calc.computeTaxCents(999, "US")).toBe(87);
  });

  it("returns 0 for zero taxable", () => {
    const calc = new RegionalTaxCalculator({ "US": 0.1 });
    expect(calc.computeTaxCents(0, "US")).toBe(0);
  });

  it("returns 0 for negative taxable", () => {
    const calc = new RegionalTaxCalculator({ "US": 0.1 });
    expect(calc.computeTaxCents(-500, "US")).toBe(0);
  });
});

describe("AsyncTaxCalculator", () => {
  it("computes tax using the resolved rate", async () => {
    const provider: AsyncTaxRateProvider = {
      getRate: vi.fn().mockResolvedValue(0.1),
    };
    const calc = new AsyncTaxCalculator(provider);
    // 10% of 5000 = 500
    expect(await calc.computeTaxCents(5000, "US")).toBe(500);
    expect(provider.getRate).toHaveBeenCalledWith("US");
  });

  it("rounds down to nearest cent", async () => {
    const provider: AsyncTaxRateProvider = {
      getRate: vi.fn().mockResolvedValue(0.0875),
    };
    const calc = new AsyncTaxCalculator(provider);
    // 8.75% of 999 = 87.4125 → 87
    expect(await calc.computeTaxCents(999, "US")).toBe(87);
  });

  it("returns 0 for zero taxable without calling provider", async () => {
    const provider: AsyncTaxRateProvider = {
      getRate: vi.fn().mockResolvedValue(0.1),
    };
    const calc = new AsyncTaxCalculator(provider);
    expect(await calc.computeTaxCents(0, "US")).toBe(0);
  });

  it("returns 0 for negative taxable", async () => {
    const provider: AsyncTaxRateProvider = {
      getRate: vi.fn().mockResolvedValue(0.1),
    };
    const calc = new AsyncTaxCalculator(provider);
    expect(await calc.computeTaxCents(-100, "US")).toBe(0);
  });

  it("throws RangeError when provider returns out-of-range rate", async () => {
    const provider: AsyncTaxRateProvider = {
      getRate: vi.fn().mockResolvedValue(1.5),
    };
    const calc = new AsyncTaxCalculator(provider);
    await expect(calc.computeTaxCents(1000, "US")).rejects.toThrow(RangeError);
  });

  it("throws RangeError when provider returns negative rate", async () => {
    const provider: AsyncTaxRateProvider = {
      getRate: vi.fn().mockResolvedValue(-0.1),
    };
    const calc = new AsyncTaxCalculator(provider);
    await expect(calc.computeTaxCents(1000, "US")).rejects.toThrow(RangeError);
  });

  it("throws RangeError when provider returns NaN", async () => {
    const provider: AsyncTaxRateProvider = {
      getRate: vi.fn().mockResolvedValue(NaN),
    };
    const calc = new AsyncTaxCalculator(provider);
    await expect(calc.computeTaxCents(1000, "US")).rejects.toThrow(RangeError);
  });

  it("propagates provider rejection", async () => {
    const provider: AsyncTaxRateProvider = {
      getRate: vi.fn().mockRejectedValue(new Error("network error")),
    };
    const calc = new AsyncTaxCalculator(provider);
    await expect(calc.computeTaxCents(1000, "US")).rejects.toThrow(
      "network error",
    );
  });
});

describe("totalLineWeightGrams", () => {
  it("sums weight * quantity across lines", () => {
    const lines: CartLine[] = [
      { product: { id: "a", name: "A", unitPriceCents: 100, weightGrams: 500 }, quantity: 2 },
      { product: { id: "b", name: "B", unitPriceCents: 200, weightGrams: 300 }, quantity: 3 },
    ];
    expect(totalLineWeightGrams(lines)).toBe(1900); // 1000 + 900
  });

  it("treats missing weightGrams as 0", () => {
    const lines: CartLine[] = [
      { product: { id: "a", name: "A", unitPriceCents: 100 }, quantity: 5 },
    ];
    expect(totalLineWeightGrams(lines)).toBe(0);
  });

  it("returns 0 for empty lines", () => {
    expect(totalLineWeightGrams([])).toBe(0);
  });
});

